<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { Fish as FishSymbol, Leaf, SlidersHorizontal, ChevronDown, Plus, Check, X, Search, Sun, Moon, Camera, Utensils, Undo2, Redo2, RotateCcw, Maximize2, Minimize2, MousePointer2, Move, Trash2, Download, Upload, CircleHelp, CheckCheck, ArrowUpRight, Waves, Settings2, Rotate3d, Eye, LoaderCircle } from 'lucide-vue-next'
import FishIcon from './FishIcon.vue'
import { species, speciesById, decorations, decorById } from './catalog'
import { initialState, uid, saveTank, loadTank, cloneState, parseState } from './model'
import type { TankState, Item } from './model'
import { AquariumScene } from './scene'
const viewport=ref<HTMLElement>();const modalElement=ref<HTMLElement>();let previousFocus:HTMLElement|null=null;const tank=ref<TankState>(initialState());const ready=ref(false);const loading=ref(true);const sceneError=ref('');const tab=ref<'fish'|'decor'>('fish');const filter=ref('all');const query=ref('');const selection=ref<string|null>(null);const placing=ref<string|null>(null);const observe=ref(false);const dialog=ref<'help'|'settings'|'residents'|'reset'|null>(null);const toast=ref('');const saveStatus=ref('正在准备');const history=ref<TankState[]>([]);const future=ref<TankState[]>([]);const cameraView=ref<'perspective'|'front'|'top'>('perspective');const feeding=ref(false);const naming=ref(false);const fileInput=ref<HTMLInputElement>();let scene:AquariumScene|null=null;let saveTimer:ReturnType<typeof setTimeout>;let toastTimer:ReturnType<typeof setTimeout>;let feedTimer:ReturnType<typeof setTimeout>;let pendingSaves:Promise<void>=Promise.resolve();let mounted=true;let transformInProgress=false;
const filteredFish=computed(()=>species.filter(s=>(filter.value==='all'||s.group===filter.value)&&(!query.value||s.name.includes(query.value)||s.latin.toLowerCase().includes(query.value.toLowerCase()))));const filteredDecor=computed(()=>decorations.filter(s=>(filter.value==='all'||s.category===filter.value)&&(!query.value||s.name.includes(query.value))));const selectedItem=computed(()=>tank.value.items.find(i=>i.uid===selection.value));const selectedDecor=computed(()=>selectedItem.value?decorById[selectedItem.value.id]:null);const residents=computed(()=>species.map(s=>({...s,count:tank.value.fish.filter(f=>f.id===s.id).length})).filter(s=>s.count));const speciesCount=computed(()=>residents.value.length);const planted=computed(()=>tank.value.items.filter(i=>decorById[i.id]?.category==='plant').length);
function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200)}
function checkpoint(){history.value.push(cloneState(tank.value));if(history.value.length>35)history.value.shift();future.value=[]}
function undo(){if(!history.value.length)return;future.value.push(cloneState(tank.value));tank.value=history.value.pop()!;selection.value=null;notify('已撤销上一步')}
function redo(){if(!future.value.length)return;history.value.push(cloneState(tank.value));tank.value=future.value.pop()!;selection.value=null;notify('已重做')}
function addFish(id:string){if(tank.value.fish.length>=30){notify('这个小世界最多容纳 30 条鱼');return}checkpoint();tank.value.fish.push({uid:uid(),id});notify(`${speciesById[id]!.name}游进了你的鱼缸`)}
function removeFish(id:string){const i=tank.value.fish.findIndex(f=>f.id===id);if(i<0)return;checkpoint();tank.value.fish.splice(i,1)}
function place(id:string,x:number,z:number){if(tank.value.items.length>=100){notify('造景数量已达到 100 件');return}checkpoint();const item:Item={uid:uid(),id,x,z,rotation:0,scale:1};tank.value.items.push(item);placing.value=null;scene?.setPlacement(null);selection.value=item.uid;notify(`${decorById[id]!.name}已放置，可在面板中调整`)}
function startPlace(id:string){if(placing.value===id){cancelPlace();return}placing.value=id;selection.value=null;scene?.setPlacement(id);notify('移动到缸底，点击放置；Esc 取消')}
function cancelPlace(){placing.value=null;scene?.setPlacement(null)}
function removeItem(){if(!selectedItem.value)return;checkpoint();tank.value.items=tank.value.items.filter(i=>i.uid!==selection.value);selection.value=null}
function endTransform(){transformInProgress=false}
function moveItem(id:string,x:number,z:number){const item=tank.value.items.find(i=>i.uid===id);if(!item)return;checkpoint();item.x=x;item.z=z}
function updateItem(field:'x'|'z'|'rotation'|'scale',e:Event){if(!selectedItem.value)return;if(!transformInProgress){checkpoint();transformInProgress=true}selectedItem.value[field]=Number((e.target as HTMLInputElement).value)}
function duplicateItem(){if(!selectedItem.value||tank.value.items.length>=100)return;checkpoint();const item={...selectedItem.value,uid:uid(),x:Math.min(2.5,selectedItem.value.x+0.25)};tank.value.items.push(item);selection.value=item.uid;notify('已复制造景')}
function resetTransform(){if(!selectedItem.value)return;checkpoint();Object.assign(selectedItem.value,{rotation:0,scale:1})}
function feed(){if(!scene)return;if(scene.feed()){feeding.value=true;notify('开饭啦，鱼儿正在靠近食物');clearTimeout(feedTimer);feedTimer=setTimeout(()=>feeding.value=false,12000)}else notify('让鱼儿慢慢享用吧')}
function light(){checkpoint();tank.value.light=!tank.value.light}
function changeSand(value:string){if(value===tank.value.sand)return;checkpoint();tank.value.sand=value}
function download(data:string,name:string){const a=document.createElement('a');a.href=data;a.download=name;document.body.appendChild(a);a.click();a.remove()}
function reload(){window.location.reload()}
async function photograph(){if(!scene)return;try{const blob=await scene.screenshot();const url=URL.createObjectURL(blob);download(url,`${tank.value.name}-水景.png`);setTimeout(()=>URL.revokeObjectURL(url),5000);notify('已拍下这一刻，照片正在下载')}catch{notify('照片保存失败，请重试')}}
function exportTank(){const blob=new Blob([JSON.stringify(tank.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);download(url,'一方水景-鱼缸存档.json');setTimeout(()=>URL.revokeObjectURL(url),1000);notify('鱼缸存档已导出')}
async function importTank(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('存档文件过大');const data=parseState(JSON.parse(await file.text()));checkpoint();tank.value=data;selection.value=null;cancelPlace();dialog.value=null;notify('已恢复导入的鱼缸')}catch(err){notify(err instanceof Error?err.message:'无法读取这个存档')}finally{(e.target as HTMLInputElement).value=''}}
function resetTank(){checkpoint();tank.value=initialState();selection.value=null;cancelPlace();dialog.value=null;notify('已恢复初始造景，可以撤销此操作')}
async function persist(){const snapshot=cloneState(tank.value);snapshot.savedAt=Date.now();pendingSaves=pendingSaves.catch(()=>{}).then(()=>saveTank(snapshot));try{await pendingSaves;if(mounted)saveStatus.value='已保存到本机'}catch{if(mounted){saveStatus.value='保存失败，请导出备份';notify('本机存档不可用，请在设置中导出鱼缸')}}}
function keyboard(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();cancelPlace();selection.value=null;dialog.value=null;observe.value=false;return}if(dialog.value&&e.key==='Tab'){const els=Array.from(modalElement.value?.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,[tabindex="0"]')??[]);const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}return}const target=e.target as HTMLElement;if(['INPUT','TEXTAREA','SELECT'].includes(target.tagName)||target.isContentEditable)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if((e.key==='Delete'||e.key==='Backspace')&&selectedItem.value){e.preventDefault();removeItem()}}
watch(dialog,async(value,old)=>{if(value){if(!old)previousFocus=document.activeElement as HTMLElement;await nextTick();modalElement.value?.querySelector<HTMLElement>('button')?.focus()}else previousFocus?.focus()});
watch(tab,()=>{filter.value='all';query.value='';cancelPlace();selection.value=null;scene?.setEditing(tab.value==='decor')});watch(selection,v=>{transformInProgress=false;scene?.select(v)});watch(observe,v=>{if(v){cancelPlace();selection.value=null}scene?.setEditing(!v&&tab.value==='decor')});watch(tank,()=>{scene?.sync(tank.value);if(!ready.value)return;saveStatus.value='正在保存…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>void persist(),650)},{deep:true});
onMounted(async()=>{try{const saved=await loadTank();if(saved)tank.value=saved;saveStatus.value=saved?'已恢复本机存档':'自动保存已开启'}catch{saveStatus.value='本机存档不可用';notify('无法读取本机存档，可使用设置中的导入与导出')}if(!mounted)return;try{scene=new AquariumScene(viewport.value!,{onSelect:id=>selection.value=id,onPlace:place,onMove:moveItem,onReady:()=>loading.value=false,onError:message=>sceneError.value=message});scene.sync(tank.value)}catch(e){loading.value=false;sceneError.value='无法创建三维画面，请检查浏览器的硬件加速设置后刷新。';console.error(e)}ready.value=true;window.addEventListener('keydown',keyboard)});
onBeforeUnmount(()=>{mounted=false;clearTimeout(saveTimer);clearTimeout(toastTimer);clearTimeout(feedTimer);if(ready.value)void persist();scene?.dispose();window.removeEventListener('keydown',keyboard)})
</script>

<template>
<div class="app-shell" :class="{'observation-mode':observe}">
 <header class="topbar" v-if="!observe" :inert="!!dialog">
  <a href="#" class="brand" aria-label="一方水景首页" @click.prevent><span class="brand-mark"><FishSymbol :size="25" :stroke-width="1.5"/></span><span><b>一方水景</b><small>A LITTLE AQUARIUM</small></span></a>
  <div class="project-name"><span class="tiny-dot"></span><input v-if="naming" v-model="tank.name" maxlength="40" aria-label="鱼缸名称" @blur="naming=false" @keydown.enter="naming=false"/><button v-else @click="naming=true" title="点击重命名">{{tank.name}} <ChevronDown :size="13"/></button><span class="version-pill">自由造景</span></div>
  <div class="header-actions"><span class="save-state"><CheckCheck :size="15"/>{{saveStatus}}</span><button class="icon-button" @click="dialog='help'" aria-label="使用帮助"><CircleHelp :size="20"/></button><button class="icon-button" @click="dialog='settings'" aria-label="鱼缸设置"><Settings2 :size="20"/></button></div>
 </header>
 <main class="workspace" :inert="!!dialog">
  <section class="aquarium-stage" aria-label="我的鱼缸">
   <div ref="viewport" class="three-viewport"></div>
   <div v-if="loading" class="loading-state"><LoaderCircle class="spin" :size="28"/><span>阳光正在照进你的鱼缸…</span></div>
   <div v-if="sceneError" class="scene-error"><Waves :size="40"/><p>{{sceneError}}</p><button class="primary-button" @click="reload">重新加载</button></div>
   <template v-if="!observe">
    <div class="scene-intro"><div class="eyebrow"><span></span>YOUR OWN LITTLE WORLD</div><h1>留一刻，<br/>给水下的慢生活<span>。</span></h1><p>一片水草，一尾游鱼。<br/>让喜欢的风景，慢慢生长。</p></div>
    <div class="scene-tag"><span class="tiny-dot"></span>淡水鱼缸<span class="tag-divider"></span>60 × 30 × 30 <small>cm</small></div>
    <div class="camera-views" aria-label="视角切换"><button v-for="v in [{id:'perspective',label:'自由',icon:Rotate3d},{id:'front',label:'正面',icon:Eye},{id:'top',label:'俯视',icon:ArrowUpRight}]" :key="v.id" :aria-label="`${v.label}视角`" :class="{active:cameraView===v.id}" @click="cameraView=v.id as typeof cameraView;scene?.changeView(cameraView)"><component :is="v.icon" :size="16"/><span>{{v.label}}</span></button></div>
    <div class="history-tools"><button class="icon-button" :disabled="!history.length" @click="undo" aria-label="撤销" title="撤销 ⌘Z"><Undo2 :size="18"/></button><button class="icon-button" :disabled="!future.length" @click="redo" aria-label="重做" title="重做 ⇧⌘Z"><Redo2 :size="18"/></button></div>
    <div v-if="placing" class="placement-hint"><MousePointer2 :size="16"/>点击缸底，放置{{decorById[placing]?.name}}<button @click="cancelPlace">取消 <kbd>esc</kbd></button></div>
    <div class="bottom-dock">
     <button class="dock-action" :class="{feeding}" @click="feed"><span class="dock-icon amber"><Utensils :size="20"/></span><span>{{feeding?'正在享用':'喂食'}}</span><i v-if="feeding" class="tiny-dot"></i></button>
     <span class="dock-divider"></span>
     <button class="dock-action" :class="{muted:!tank.light}" @click="light"><span class="dock-icon"><Sun v-if="tank.light" :size="21"/><Moon v-else :size="20"/></span><span>{{tank.light?'灯光开启':'灯光关闭'}}</span></button>
     <button class="dock-action" @click="photograph"><span class="dock-icon"><Camera :size="21"/></span><span>拍张照片</span></button>
     <span class="dock-divider"></span>
     <button class="dock-action observe-button" @click="observe=true"><Maximize2 :size="18"/><span>静静观赏</span></button>
    </div>
    <div class="scene-footer"><span><MousePointer2 :size="13"/> 拖动旋转</span><span><Move :size="13"/> 滚轮缩放</span><button @click="scene?.changeView('perspective');cameraView='perspective'">重置视角</button></div>
   </template>
   <template v-else><button class="exit-observe" @click="observe=false"><Minimize2 :size="17"/>返回工作台</button><div class="observation-caption"><span>一方水景</span><small>{{tank.name}}</small></div></template>
  </section>
  <aside class="sidebar" v-if="!observe">
   <div class="sidebar-title"><div><span class="eyebrow">MAKE IT YOURS</span><h2>布置你的小世界</h2></div><span class="edition">VOL. 01</span></div>
   <div class="library-tabs"><button :class="{active:tab==='fish'}" @click="tab='fish'"><FishSymbol :size="18"/>鱼儿 <span>10</span></button><button :class="{active:tab==='decor'}" @click="tab='decor'"><Leaf :size="18"/>造景 <span>{{decorations.length}}</span></button></div>
   <div class="library-controls"><div class="search-box"><Search :size="16"/><input v-model="query" :placeholder="tab==='fish'?'找一位水下新朋友':'寻找水草、石头或沉木'" aria-label="搜索素材"/><button v-if="query" class="icon-button" @click="query=''" aria-label="清除搜索"><X :size="14"/></button></div>
   <div class="filter-tabs" v-if="tab==='fish'"><button v-for="f in [{id:'all',label:'全部'},{id:'cold',label:'冷水鱼'},{id:'warm',label:'热带 / 广温'}]" :key="f.id" :class="{active:filter===f.id}" @click="filter=f.id">{{f.label}}</button></div>
   <div class="filter-tabs" v-else><button v-for="f in [{id:'all',label:'全部'},{id:'plant',label:'水草'},{id:'rock',label:'石景'},{id:'wood',label:'沉木'}]" :key="f.id" :class="{active:filter===f.id}" @click="filter=f.id">{{f.label}}</button></div></div>
   <div class="library-scroll" :class="{'has-selection':selectedItem}">
    <div class="library-section-heading"><span>{{tab==='fish'?'遇见水下的邻居':'好风景，从这里开始'}}</span><small>{{tab==='fish'?filteredFish.length:filteredDecor.length}} {{tab==='fish'?'种鱼儿':'件素材'}}</small></div>
    <div v-if="tab==='fish'" class="fish-grid"><button v-for="fish in filteredFish" :key="fish.id" class="fish-card" @click="addFish(fish.id)" :aria-label="`添加${fish.name}`" :title="fish.note"><div class="fish-card-art" :class="fish.group"><span class="fish-type-dot" :class="fish.group"></span><FishIcon :fish="fish"/><span class="add-badge"><Plus :size="16"/></span><span v-if="tank.fish.some(f=>f.id===fish.id)" class="owned-count">{{tank.fish.filter(f=>f.id===fish.id).length}} 尾</span></div><div class="fish-card-info"><strong>{{fish.name}}</strong><span>{{fish.label}}</span></div></button></div>
    <div v-else class="decor-grid"><button v-for="d in filteredDecor" :key="d.id" class="decor-card" :class="{selected:placing===d.id}" @click="startPlace(d.id)"><div class="decor-art" :class="d.id"><svg v-if="d.category==='plant'" viewBox="0 0 120 86" :style="{color:d.color}"><path v-for="i in 7" :key="i" :d="`M60 77 Q${20+i*10} ${45-i*3} ${20+i*11} ${13+(i%3)*8} Q${45+i*4} 38 60 77`" fill="currentColor" :opacity=".55+(i%3)*.2"/></svg><svg v-else-if="d.category==='rock'" viewBox="0 0 120 86"><path :d="d.id==='pebble'?'M22 62 Q17 40 43 33 Q77 19 98 46 Q109 68 73 72 Q32 77 22 62':'M18 65 L27 41 L47 23 L75 21 L98 43 L103 63 L73 73 L38 73Z'" :fill="d.color"/><path d="M27 41 L56 44 L75 21 L68 54 L103 63 L73 73 L53 61 L38 73Z" fill="#464c40" opacity=".16"/></svg><svg v-else viewBox="0 0 120 86"><path d="M33 77 Q69 57 62 29 L71 10 M61 40 L39 27 L24 28 M60 52 L83 42 L98 22 M62 65 L85 70" fill="none" :stroke="d.color" stroke-width="7" stroke-linecap="round"/><path d="M39 27 L37 13 M83 42 L91 45" fill="none" :stroke="d.color" stroke-width="3" stroke-linecap="round"/></svg><span class="add-badge"><Plus :size="16"/></span></div><strong>{{d.name}}</strong><small>{{d.category==='plant'?'水草':d.category==='rock'?'石景':'沉木'}}</small></button></div>
    <div v-if="!(tab==='fish'?filteredFish.length:filteredDecor.length)" class="empty-state"><Search :size="24"/><p>暂时没有找到，换个关键词吧</p></div>
    <div class="library-note"><Leaf :size="16"/><span>{{tab==='fish'?'自由创作模式，可搭配不同鱼种。真实饲养请另行确认混养条件。':'选择素材后点击缸底放置，再调整位置、大小与方向。'}}</span></div>
   </div>
   <section v-if="selectedItem&&selectedDecor" class="transform-panel"><div class="transform-title"><span><SlidersHorizontal :size="16"/>{{selectedDecor.name}}</span><button class="icon-button" @click="selection=null" aria-label="取消选中"><X :size="16"/></button></div><label>旋转 <input type="range" min="-3.14" max="3.14" step="0.02" :value="selectedItem.rotation" @input="updateItem('rotation',$event)" @change="endTransform" @blur="endTransform"/><output>{{Math.round(selectedItem.rotation*180/Math.PI)}}°</output></label><label>大小 <input type="range" min="0.4" max="1.8" step="0.05" :value="selectedItem.scale" @input="updateItem('scale',$event)" @change="endTransform" @blur="endTransform"/><output>{{Math.round(selectedItem.scale*100)}}%</output></label><label>左右 <input type="range" min="-2.5" max="2.5" step="0.05" :value="selectedItem.x" @input="updateItem('x',$event)" @change="endTransform" @blur="endTransform"/><output>{{selectedItem.x.toFixed(1)}}</output></label><label>前后 <input type="range" min="-1.15" max="1.15" step="0.05" :value="selectedItem.z" @input="updateItem('z',$event)" @change="endTransform" @blur="endTransform"/><output>{{selectedItem.z.toFixed(1)}}</output></label><div class="transform-actions"><button @click="resetTransform"><RotateCcw :size="14"/>重置</button><button @click="duplicateItem"><Plus :size="14"/>复制</button><button class="danger" @click="removeItem"><Trash2 :size="14"/>移除</button></div></section>
   <button class="tank-summary" @click="dialog='residents'"><span class="summary-icon"><Waves :size="21"/></span><span><strong>我的水下居民 <b>{{tank.fish.length}}</b></strong><small>{{speciesCount}} 种鱼儿 · {{planted}} 处水草</small></span><span class="summary-arrow"><ArrowUpRight :size="18"/></span></button>
  </aside>
 </main>
 <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Check :size="17"/>{{toast}}</div></Transition>
 <div v-if="dialog" class="modal-overlay" @click.self="dialog=null"><section ref="modalElement" class="modal" role="dialog" aria-modal="true" :aria-label="dialog==='settings'?'鱼缸设置':dialog==='residents'?'水下居民':dialog==='reset'?'重置鱼缸':'欢迎来到一方水景'"><button class="modal-close icon-button" @click="dialog=null" aria-label="关闭"><X :size="21"/></button>
  <template v-if="dialog==='help'"><span class="modal-eyebrow">A LITTLE MOMENT FOR YOURSELF</span><h2>欢迎来到一方水景</h2><p class="modal-description">给自己一点时间，布置一个喜欢的小世界。</p><div class="help-steps"><div><span>01</span><section><h3>遇见新朋友</h3><p>点击鱼儿卡片，把它放入鱼缸。点击“水下居民”可以查看或移出。</p></section></div><div><span>02</span><section><h3>把风景变成你的</h3><p>切到造景，选择素材，再点击缸底放置。拖动已有造景可移动，选中后可调整大小和方向。</p></section></div><div><span>03</span><section><h3>慢下来，看一会儿</h3><p>拖动旋转视角，滚轮缩放。喂一次食，拍张照片，或者隐藏界面静静观赏。</p></section></div></div><div class="keyboard-note"><kbd>⌘ / Ctrl Z</kbd> 撤销 <kbd>Esc</kbd> 退出操作</div><button class="primary-button" @click="dialog=null">开始我的水下生活 <ArrowUpRight :size="16"/></button></template>
  <template v-else-if="dialog==='residents'"><span class="modal-eyebrow">YOUR UNDERWATER NEIGHBOURS</span><h2>我的水下居民 <small>{{tank.fish.length}} / 30</small></h2><p class="modal-description">{{speciesCount}} 种小伙伴，共享这一方风景。</p><div class="resident-list"><div v-for="fish in residents" :key="fish.id" class="resident-row"><FishIcon :fish="fish"/><div><strong>{{fish.name}}</strong><small>{{fish.temperature}} · {{fish.label}}</small></div><span>{{fish.count}} 尾</span><button class="icon-button" @click="removeFish(fish.id)" :aria-label="`移出一条${fish.name}`"><Trash2 :size="16"/></button></div><div v-if="!residents.length" class="empty-state">鱼缸还很安静，去邀请几位小伙伴吧。</div></div><button class="primary-button" @click="dialog=null;tab='fish'">认识更多鱼儿 <Plus :size="16"/></button></template>
  <template v-else-if="dialog==='settings'"><span class="modal-eyebrow">THE LITTLE DETAILS</span><h2>鱼缸设置</h2><label class="setting-label">给鱼缸取个名字<input v-model="tank.name" maxlength="40" placeholder="我的水下花园"/></label><div class="setting-label">底砂颜色<div class="sand-options"><button v-for="s in [{id:'natural',name:'原色细砂',color:'#cdbb96'},{id:'white',name:'浅色细砂',color:'#f1e7d2'},{id:'dark',name:'深色细砂',color:'#656b5b'}]" :key="s.id" :class="{active:tank.sand===s.id}" @click="changeSand(s.id)"><span :style="{background:s.color}"></span>{{s.name}}<Check v-if="tank.sand===s.id" :size="14"/></button></div></div><div class="setting-row"><span><strong>水草灯</strong><small>为你的小世界点亮一束光</small></span><button class="toggle" :class="{on:tank.light}" @click="light" role="switch" :aria-checked="tank.light" aria-label="水草灯"><i></i></button></div><div class="backup-actions"><button @click="exportTank"><Download :size="17"/>导出存档</button><button @click="fileInput?.click()"><Upload :size="17"/>导入存档</button></div><p class="settings-note">鱼缸自动保存在当前浏览器。导出存档可备份或迁移到其他设备。</p><button class="reset-button" @click="dialog='reset'"><RotateCcw :size="15"/>恢复初始造景</button></template>
  <template v-else-if="dialog==='reset'"><span class="modal-eyebrow">A FRESH LITTLE START</span><h2>重新布置这方风景？</h2><p class="modal-description">鱼缸将恢复为初始造景和居民。你也可以在重置后撤销，或先导出一份存档。</p><div class="confirm-actions"><button class="secondary-button" @click="dialog='settings'">返回设置</button><button class="primary-button" @click="resetTank">恢复初始造景</button></div></template>
 </section></div>
 <input ref="fileInput" type="file" accept="application/json,.json" class="visually-hidden" aria-label="导入鱼缸存档" @change="importTank"/>
</div>
</template>
